package com.opensocket.aievent.core.capability.runtime;
import org.springframework.beans.factory.DisposableBean;import org.springframework.beans.factory.InitializingBean;import org.springframework.beans.factory.annotation.Qualifier;import org.springframework.scheduling.TaskScheduler;import org.springframework.stereotype.Component;import com.opensocket.aievent.core.capability.SemanticTriageAdaptiveRoutingWorker;import com.opensocket.aievent.core.configuration.runtime.DynamicFixedDelayTask;
@Component public final class SemanticTriageDynamicScheduler implements InitializingBean,DisposableBean {private final DynamicFixedDelayTask task;public SemanticTriageDynamicScheduler(SemanticTriageRuntimeConfigurationView runtime,SemanticTriageAdaptiveRoutingWorker worker,@Qualifier("reconciliationOperationalScheduler") TaskScheduler scheduler){task=new DynamicFixedDelayTask(scheduler,"semantic-triage",worker::tick,runtime::workerDelay);}public void afterPropertiesSet(){task.start();}public void destroy(){task.stop();}}
